package net.civeira.phylax.feature.access.oauthclient.domain.valueholder;

import java.util.Optional;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;
import org.mockito.Mockito;

import net.civeira.phylax.common.value.validation.ConstraintFailList;
import net.civeira.phylax.feature.access.oauthclient.domain.OauthClient;
import net.civeira.phylax.feature.access.oauthclient.domain.valueobject.UserinfoEncryptedResponseEncVO;

class UserinfoEncryptedResponseEncValueHolderUnitTest {

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test assign plain values on the holder of userinfo encrypted response enc of oauth client")
  void test_userinfo_encrypted_response_enc_value_holder_assign_plain_value() {
    Object holder = new Object();
    UserinfoEncryptedResponseEncValueHolder<Object> value =
        new UserinfoEncryptedResponseEncValueHolder<>(holder);
    Assertions.assertSame(holder, value.userinfoEncryptedResponseEnc("one"),
        "Setters must return the holder");
    Assertions.assertTrue(value.getUserinfoEncryptedResponseEncValue().isPresent(),
        "The plain value must be stored");
    Assertions.assertEquals("one", value.getUserinfoEncryptedResponseEnc().orElse(null),
        "The plain value must be recovered");
    Assertions.assertSame(holder, value.userinfoEncryptedResponseEncNull(),
        "Setters must return the holder");
    Assertions.assertTrue(value.getUserinfoEncryptedResponseEncValue().isPresent(),
        "A null value object must be stored");
    Assertions.assertFalse(value.getUserinfoEncryptedResponseEnc().isPresent(),
        "A null value must not have content");
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test assign value objects on the holder of userinfo encrypted response enc of oauth client")
  void test_userinfo_encrypted_response_enc_value_holder_assign_value_object() {
    Object holder = new Object();
    UserinfoEncryptedResponseEncValueHolder<Object> value =
        new UserinfoEncryptedResponseEncValueHolder<>(holder);
    UserinfoEncryptedResponseEncVO vo = UserinfoEncryptedResponseEncVO.from("one");
    Assertions.assertFalse(value.getUserinfoEncryptedResponseEncValue().isPresent(),
        "A new holder must be empty");
    Assertions.assertSame(holder, value.userinfoEncryptedResponseEnc(vo),
        "Setters must return the holder");
    Assertions.assertSame(vo, value.getUserinfoEncryptedResponseEncValue().orElseThrow());
    Assertions.assertSame(holder, value.userinfoEncryptedResponseEnc(Optional.empty()));
    Assertions.assertFalse(value.getUserinfoEncryptedResponseEncValue().isPresent(),
        "An empty optional must clear the value");
    Assertions.assertSame(holder, value.userinfoEncryptedResponseEnc(Optional.of(vo)));
    Assertions.assertSame(vo, value.getUserinfoEncryptedResponseEncValue().orElseThrow());
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test read the value of the holder of userinfo encrypted response enc of oauth client against the original")
  void test_userinfo_encrypted_response_enc_value_holder_read() {
    Object holder = new Object();
    UserinfoEncryptedResponseEncValueHolder<Object> value =
        new UserinfoEncryptedResponseEncValueHolder<>(holder);
    UserinfoEncryptedResponseEncVO vo = UserinfoEncryptedResponseEncVO.from("one");
    UserinfoEncryptedResponseEncVO other = UserinfoEncryptedResponseEncVO.from("one");
    OauthClient original = Mockito.mock(OauthClient.class);
    Mockito.when(original.getUserinfoEncryptedResponseEncValue()).thenReturn(other);
    ConstraintFailList fails = new ConstraintFailList();
    Assertions.assertSame(other,
        value.readUserinfoEncryptedResponseEnc(Optional.of(original), fails),
        "Without value, the original must be used");
    Assertions.assertTrue(fails.isEmpty());
    Assertions.assertNotNull(value.readUserinfoEncryptedResponseEnc(Optional.empty(), fails),
        "Without value and original a null value is returned");
    Assertions.assertTrue(fails.isEmpty(), "An optional value is never reported as missing");
    value.userinfoEncryptedResponseEnc(vo);
    ConstraintFailList others = new ConstraintFailList();
    Assertions.assertSame(vo, value.readUserinfoEncryptedResponseEnc(Optional.of(original), others),
        "With value, the original is ignored");
    Assertions.assertSame(vo, value.readUserinfoEncryptedResponseEnc(Optional.empty(), others));
    Assertions.assertTrue(others.isEmpty());
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test unset the value of the holder of userinfo encrypted response enc of oauth client")
  void test_userinfo_encrypted_response_enc_value_holder_unset() {
    Object holder = new Object();
    UserinfoEncryptedResponseEncValueHolder<Object> value =
        new UserinfoEncryptedResponseEncValueHolder<>(holder);
    UserinfoEncryptedResponseEncVO vo = UserinfoEncryptedResponseEncVO.from("one");
    value.userinfoEncryptedResponseEnc(vo);
    Assertions.assertSame(holder,
        value.unsetUserinfoEncryptedResponseEncIfMatches("userinfoEncryptedResponseEnc_other"));
    Assertions.assertTrue(value.getUserinfoEncryptedResponseEncValue().isPresent(),
        "Other field name must keep the value");
    Assertions.assertSame(holder,
        value.unsetUserinfoEncryptedResponseEncIfMatches("userinfoEncryptedResponseEnc"));
    Assertions.assertFalse(value.getUserinfoEncryptedResponseEncValue().isPresent(),
        "The field name must clear the value");
    value.userinfoEncryptedResponseEnc(vo);
    Assertions.assertSame(holder, value.unsetUserinfoEncryptedResponseEnc());
    Assertions.assertFalse(value.getUserinfoEncryptedResponseEncValue().isPresent(),
        "Unset must clear the value");
  }
}
